import { tokenGuidance } from '../packages/design-tokens/guidance/catalog.ts';
import { uiGuidance } from '../packages/ui/guidance/catalog.ts';
import { illustrationGuidance } from '../packages/ui/guidance/illustrations.ts';
import { noGuidance } from '../packages/ui/guidance/no-guidance.ts';
import { screenRecipes } from '../packages/ui/guidance/recipes.ts';
import { publicComponents } from './public-components.ts';

const root = new URL('../', import.meta.url);
const checkOnly = Bun.argv.includes('--check');
const generatedHeader =
  '<!-- Generated by bun run skills:generate. Edit the guidance source, not this file. -->';

function sectionTitle(title: string) {
  return `## ${title}`;
}

const code = (name: string) => `\`${name}\``;

function renderDoNotHandRoll() {
  const rows = uiGuidance.flatMap((entry) =>
    (entry.replaces ?? []).map(
      (item) => `| ${item.pattern} | ${item.use.map(code).join(', ')} | ${entry.title} |`,
    ),
  );
  return [
    sectionTitle('Do not hand-roll'),
    '',
    'Before you build one of these by hand, use the component. Then read its section below.',
    '',
    '| Hand-built pattern | Use | Section |',
    '| --- | --- | --- |',
    ...rows,
  ].join('\n');
}

function renderComponentDecisions() {
  const entries = uiGuidance.map((entry) => {
    const choices = entry.choices?.length
      ? [
          '',
          '**Choose:**',
          '',
          ...entry.choices.map((choice) => `- \`${choice.choice}\`: ${choice.when}`),
        ]
      : [];
    const replaces = entry.replaces?.length
      ? [
          '',
          '**Instead of:**',
          '',
          ...entry.replaces.map(
            (item) => `- ${item.pattern}: use ${item.use.map(code).join(', ')}.`,
          ),
        ]
      : [];
    const related = entry.related?.length
      ? ['', `Related decisions: ${entry.related.map((id) => `\`${id}\``).join(', ')}.`]
      : [];

    return [
      sectionTitle(entry.title),
      '',
      entry.summary,
      '',
      `Components: ${entry.components.map(code).join(', ')}.`,
      '',
      ...entry.rules.map((rule) => `- **${rule.title}:** ${rule.body}`),
      ...choices,
      ...replaces,
      ...related,
    ].join('\n');
  });

  return [
    generatedHeader,
    '# Vendure UI component decisions',
    '',
    'Use these rules to select and compose components. Inspect the installed package source and types for exact APIs.',
    '',
    renderDoNotHandRoll(),
    '',
    ...entries,
    '',
  ].join('\n');
}

function renderScreenRecipes() {
  const entries = screenRecipes.map((recipe) =>
    [
      sectionTitle(recipe.title),
      '',
      recipe.purpose,
      '',
      '**Invariants:**',
      '',
      ...recipe.invariants.map((invariant) => `- ${invariant}`),
      '',
      '### Dashboard extension integration',
      '',
      'The Dashboard owns the exact page-layout, registration, form, navigation, and action APIs. Inspect the installed `@vendure/dashboard` source and types, then apply this intent without recreating a standalone page shell:',
      '',
      ...recipe.dashboardIntent.map((intent) => `- ${intent}`),
      '',
      '### Standalone consumer skeleton',
      '',
      '```tsx',
      recipe.standaloneSkeleton,
      '```',
    ].join('\n'),
  );

  return [
    generatedHeader,
    '# Vendure screen recipes',
    '',
    'Treat these as strong defaults. Begin from the closest recipe and preserve its hierarchy, action placement, responsive anatomy, and state handling. Deviate only for a concrete product requirement and report the reason.',
    '',
    ...entries,
    '',
  ].join('\n');
}

function renderIllustrations() {
  return [
    generatedHeader,
    '# Illustration selection',
    '',
    'Use one scenario-matched illustration for a whole empty or error region. Never repeat illustrations in table rows, list items, or cards inside an otherwise populated view; use a bare-icon fallback or no media there.',
    '',
    'Pass the illustration as `illustration` to `EmptyState` or `ErrorState`. Each row names the state it is for and the nearest state it is not for.',
    '',
    '| State | Illustration | Not for |',
    '| --- | --- | --- |',
    ...illustrationGuidance.map(
      (item) => `| ${item.use} | \`${item.component}\` | ${item.notFor} |`,
    ),
    '',
  ].join('\n');
}

function renderTokenDecisions() {
  const entries = tokenGuidance.map((entry) =>
    [
      sectionTitle(entry.title),
      '',
      entry.summary,
      '',
      ...entry.rules.map((rule) => `- **${rule.title}:** ${rule.body}`),
    ].join('\n'),
  );

  return [
    generatedHeader,
    '# Vendure token decisions',
    '',
    'Apply these decisions to theme setup, styling, implementation, and review. Actual values remain authoritative in the installed design-tokens package.',
    '',
    ...entries,
    '',
  ].join('\n');
}

const outputs = new Map<string, string>([
  ['skills/vendure-ui/references/component-decisions.md', renderComponentDecisions()],
  ['skills/vendure-ui/references/screen-recipes.md', renderScreenRecipes()],
  ['skills/vendure-ui/references/illustrations.md', renderIllustrations()],
  ['skills/vendure-tokens/references/token-decisions.md', renderTokenDecisions()],
]);

/**
 * Compound parts named `<Parent><Slot>` are covered through their parent, so
 * `DialogHeader` needs no entry once `Dialog` has one. The list holds layout
 * slots only. A part with its own job, such as `CardLink`, `TabsLink` or
 * `BreadcrumbMenu`, must be named in an entry: never add `Link`, `Menu`,
 * `Button` or `Dialog` here.
 */
const structuralSlots = [
  'Action',
  'Actions',
  'Addon',
  'Badge',
  'Body',
  'Cancel',
  'Caption',
  'Cell',
  'CheckboxItem',
  'Chip',
  'Chips',
  'Close',
  'Collection',
  'Content',
  'Controls',
  'Count',
  'DayButton',
  'Description',
  'Detail',
  'Ellipsis',
  'Empty',
  'Fallback',
  'Footer',
  'Group',
  'Guide',
  'Handle',
  'Head',
  'Header',
  'Image',
  'Indicator',
  'Input',
  'Item',
  'Label',
  'Leading',
  'Legend',
  'List',
  'Media',
  'Meta',
  'Next',
  'OptGroup',
  'Option',
  'Overlay',
  'Panel',
  'Portal',
  'Positioner',
  'Previous',
  'RadioGroup',
  'RadioItem',
  'Rail',
  'Row',
  'ScrollDownButton',
  'ScrollUpButton',
  'Separator',
  'Shortcut',
  'Skeleton',
  'Slot',
  'Step',
  'Sub',
  'SwipeHandle',
  'Text',
  'Textarea',
  'Title',
  'Track',
  'Trigger',
  'Value',
];

/** PascalCase words in guidance prose that are not components: icons, libraries, state names, types. */
const proseNames = new Set([
  'ArrowUpRight',
  'CircleAlert',
  'DataTableColumnMeta',
  'MoreHorizontal',
  'TanStack',
  'TriangleAlert',
  'TruckIcon',
  'ValidatingCustomer',
]);

function validateCoverage() {
  const exported = publicComponents();
  const errors: string[] = [];
  const owner = new Map<string, string>();
  const named = (name: string, where: string) => {
    if (!exported.has(name)) {
      errors.push(`${where} names \`${name}\`, which is not a public component export.`);
    }
  };

  for (const entry of uiGuidance) {
    if (entry.components.length === 0) errors.push(`${entry.id} declares no components.`);
    for (const name of entry.components) {
      named(name, `Catalog entry ${entry.id}`);
      const previous = owner.get(name);
      if (previous) errors.push(`\`${name}\` is declared by both ${previous} and ${entry.id}.`);
      owner.set(name, entry.id);
    }
    for (const item of entry.replaces ?? []) {
      if (item.use.length === 0)
        errors.push(`${entry.id} replaces "${item.pattern}" with nothing.`);
      for (const name of item.use) named(name, `Catalog entry ${entry.id} (replaces)`);
    }
  }
  // A slot covers a part only through a parent from the same module, so
  // `ToggleGroup` is not a part of `Toggle`.
  const parentOf = (name: string): string[] =>
    structuralSlots
      .filter((slot) => name.endsWith(slot) && name.length > slot.length)
      .map((slot) => name.slice(0, -slot.length))
      .filter((parent) => exported.get(parent) === exported.get(name));
  const covered = (name: string): boolean => owner.has(name) || parentOf(name).some(covered);

  // Every declared component, and every component-like name in the prose, is
  // checked, so a rename cannot leave advice about a name that no longer exists.
  const mentions = (text: string, name: string) => new RegExp(`\\b${name}\\b`).test(text);
  for (const entry of uiGuidance) {
    const { id, sourceStory, components, related, ...prose } = entry;
    const text = JSON.stringify(prose);
    for (const name of components) {
      const parents = (n: string): string[] => [n, ...parentOf(n).flatMap(parents)];
      if (!parents(name).some((n) => mentions(text, n))) {
        errors.push(`Catalog entry ${id} declares \`${name}\` but its text never names it.`);
      }
    }
    for (const [word] of text.matchAll(/\b[A-Z][a-z0-9]+(?:[A-Z][a-z0-9]*)+\b/g)) {
      const singular = word.endsWith('s') ? word.slice(0, -1) : word;
      if (!exported.has(word) && !exported.has(singular) && !proseNames.has(word)) {
        errors.push(
          `Catalog entry ${id} mentions \`${word}\`, which is not a public component export. Fix the name, or add it to proseNames if it is not a component.`,
        );
      }
    }
  }

  for (const item of illustrationGuidance) {
    named(item.component, 'illustrations.ts');
    owner.set(item.component, 'illustrations');
  }
  for (const item of noGuidance) {
    named(item.component, 'no-guidance.ts');
    if (owner.has(item.component)) {
      errors.push(`\`${item.component}\` is in no-guidance.ts but has guidance.`);
    }
    owner.set(item.component, 'no-guidance');
  }

  const missing = new Map<string, string[]>();
  for (const [name, subpath] of exported) {
    if (!covered(name)) missing.set(subpath, [...(missing.get(subpath) ?? []), name]);
  }
  if (missing.size > 0) {
    errors.push(
      'Public components without guidance. Add each to the `components` of a catalog entry, or to no-guidance.ts with a reason:',
      ...Array.from(missing, ([subpath, names]) => `- ${subpath.slice(2)}: ${names.join(', ')}`),
    );
  }

  if (errors.length > 0) throw new Error(errors.join('\n'));
}

function validateCatalog() {
  const ids = uiGuidance.map((entry) => entry.id);
  const duplicateIds = ids.filter((id, index) => ids.indexOf(id) !== index);
  if (duplicateIds.length > 0) {
    throw new Error(`Duplicate UI guidance ids: ${duplicateIds.join(', ')}`);
  }

  const storyDirectory = new URL('packages/ui/stories/', root);
  const coveredStories = new Set(uiGuidance.map((entry) => entry.sourceStory));
  const guidanceStories = Array.from(
    new Bun.Glob('*-guidance.stories.tsx').scanSync({ cwd: storyDirectory.pathname }),
  ).filter((story) => story !== 'token-guidance.stories.tsx');

  const missingCatalogEntries = guidanceStories.filter((story) => !coveredStories.has(story));
  const missingStoryFiles = Array.from(coveredStories).filter(
    (story) => !guidanceStories.includes(story),
  );

  if (missingCatalogEntries.length > 0 || missingStoryFiles.length > 0) {
    throw new Error(
      [
        missingCatalogEntries.length
          ? `Guidance stories missing catalog entries: ${missingCatalogEntries.join(', ')}`
          : '',
        missingStoryFiles.length
          ? `Catalog entries missing guidance stories: ${missingStoryFiles.join(', ')}`
          : '',
      ]
        .filter(Boolean)
        .join('\n'),
    );
  }

  validateCoverage();

  for (const recipe of screenRecipes) {
    if (recipe.dashboardIntent.length === 0) {
      throw new Error(`Screen recipe ${recipe.id} needs Dashboard integration intent.`);
    }
    if (recipe.dashboardIntent.some((intent) => intent.includes("from '@vendure/dashboard'"))) {
      throw new Error(
        `Screen recipe ${recipe.id} must not claim exact Dashboard imports owned by another repository.`,
      );
    }
  }
}

validateCatalog();

const stale: string[] = [];
for (const [path, content] of outputs) {
  const file = Bun.file(new URL(path, root));
  const current = (await file.exists()) ? await file.text() : '';
  if (current === content) {
    continue;
  }
  if (checkOnly) {
    stale.push(path);
    continue;
  }
  await Bun.write(file, content);
}

if (stale.length > 0) {
  console.error(
    `Generated skill references are stale:\n${stale.map((path) => `- ${path}`).join('\n')}`,
  );
  console.error('Run `bun run skills:generate` and commit the results.');
  process.exit(1);
}

console.log(checkOnly ? 'Skill references are fresh.' : 'Generated skill references.');
